-- 展示唐僧框架信息

local function InfoTangSeng(world, debugger: ITangSengDebugger, services: IServiceProvider)
	local ui = debugger:getWidgets()

	ui.window({
		title = `唐僧调试信息`,
		closable = true,
		minSize = Vector2.new(200, 10),
		maxSize = Vector2.new(300, 300),
	}, function()
		local debugInfo = services:GetRequiredService("ITangSengDebugInfo")
		for key, provider in debugInfo:GetAllInfos() do
			ui.label(`{key} : {provider}`)
		end
	end)
end

return InfoTangSeng
